/**
 * SOURCES-DO-FREE-DISCOVERY-1 — DGII activity text → CIIU.DR 2009 code(s).
 *
 * DATA FILE. Generated once, reviewed, committed. Do not edit by hand.
 *
 * Provenance:
 *   - `text`: the activity text EXACTLY as the DGII RNC registry stores it in
 *     `source_company_snapshots.sector` (source_key `rd_dgii_bulk`). DGII cuts
 *     it at 30 characters. Only texts of ACTIVE taxpayers were read (read-only
 *     query against Production, 2026-09-29).
 *   - `codes` / `description`: the Clasificador Dominicano de Actividades
 *     Económicas CIIU.DR 2009 (DGII, public), every activity whose description
 *     starts with that text (accents, case and punctuation ignored).
 *     `description` is the first match, as extracted from the PDF.
 *
 * Texts that match no catalog activity are NOT listed: they never get a macro
 * industry (fail-closed), they are never invented.
 */

export type DgiiActivityCatalogEntry = {
  /** Activity text exactly as DGII stores it (≤ 30 characters). */
  readonly text: string;
  /** CIIU.DR 2009 six-digit codes whose description starts with `text`. */
  readonly codes: readonly string[];
  /** Full CIIU.DR description of the first code. Display only. */
  readonly description: string;
};

